import sys
import os
sys.path.insert(0, os.path.dirname(__file__))

from extract_epic import handler, epic_extract_process
from unittest.mock import patch, MagicMock
import requests as req


def test_handler_with_env_vars():
    """Test that handler works when environ contains EPIC_BASE_URL"""
    print("Testing handler function with EPIC_BASE_URL in environment...")

    # Simulate what Terraform provides via environment variables
    mock_environ = {
        'EPIC_BASE_URL': 'https://graphql.epicgames.com/graphql',
